// Owns the two-line rewrite's text (docs/CARD-STYLE-SAMPLES.md): every card's decision and
// buying_tips (and egg_labels sources) equal the pin in twoLinePin.js, which older batch tests read through.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { nonEmpty } from '../../lib/testGuards.js';
import { TWO_LINE } from './twoLinePin.js';
import { matchItemToCard } from '../../lib/listMatch.js';

const kb = JSON.parse(readFileSync(new URL('../../kristy_perimeter_kb.json', import.meta.url), 'utf8'));

test('every card carries the pinned two-line decision and buying_tips', () => {
  const cards = nonEmpty(kb.entries.filter((e) => e.kind !== 'pick'), 'cards', 180);
  for (const e of cards) {
    assert.ok(TWO_LINE[e.id], `${e.id} has no two-line pin`);
    // Every pinned field, so a field the older tests restore (cart_pick, pick_steps) is still checked live.
    for (const [k, v] of Object.entries(TWO_LINE[e.id])) assert.deepEqual(e[k], v, `${e.id}.${k}`);
  }
  assert.equal(Object.keys(TWO_LINE).length, cards.length, 'a pin for a card that is gone');
});

// Known gap: lintSections L5 makes the chuck pick carry the G1 term, and that term alone outscores
// beef_cuts_basics for beef_grassfed_vs_grainfed (scorePool's top-2 window), so the pick lands uncarded.
// Pinned null so a matcher or wording change that fixes it (or sends it to the wrong card) goes red.
const KNOWN_UNCARDED = new Set(['beef_cuts_basics']);
test('every pinned cart_pick resolves to its own card on the live KB', () => {
  const ids = nonEmpty(Object.keys(TWO_LINE).filter((id) => TWO_LINE[id].cart_pick), 'pinned cart picks', 3);
  for (const id of ids) {
    const m = matchItemToCard(kb.entries.find((e) => e.id === id).cart_pick);
    assert.equal(m ? m.slug ?? m.id ?? m.entry?.id : null, KNOWN_UNCARDED.has(id) ? null : id, `${id} cart_pick`);
  }
});
// Written by the planner; do not edit.
// ca-3b: docs/CARD-ALIGNMENT-PLAN.md "CA-3 Meat batch", CA-3b rows. D8: chicken_breast is rewritten, not folded.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import * as lint from '../../lib/counterCardLint.js';
import * as pass from './passRule.js';
import { RETIRED, projectEntry } from '../../lib/counterCards.js';

const SERVER = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const ROOT = join(SERVER, '..');
const kb = JSON.parse(readFileSync(join(SERVER, 'kristy_perimeter_kb.json'), 'utf8'));
const doLines = JSON.parse(readFileSync(join(SERVER, 'lib', 'doLines.json'), 'utf8'));
const BASE = 'aa12a3d';
const PRE = JSON.parse(execFileSync('git', ['show', `${BASE}:server/kristy_perimeter_kb.json`], { cwd: ROOT, maxBuffer: 64 << 20 }).toString());
const now = (id) => kb.entries.find((e) => e.id === id);
const pre = (id) => PRE.entries.find((e) => e.id === id);
const words = (s) => String(s || '').trim().split(/\s+/).filter(Boolean).length;
const flat = (r) => (Array.isArray(r) ? r : (r && r.violations) || []);
const RETIRED_IDS = new Set([...(RETIRED || [])].map((r) => (typeof r === 'string' ? r : r.id)));

const BATCH = ['pork_cuts_and_enhanced', 'pick_sausage', 'pick_jerky', 'chicken_cuts_basics', 'chicken_breast', 'rotisserie_chicken',
  'turkey_whole', 'ground_turkey', 'bacon', 'ham', 'hot_dogs', 'turkey_bacon', 'cured_pork', 'deli_meat_uncured'];
const CURED = ['bacon', 'ham', 'hot_dogs', 'turkey_bacon', 'cured_pork', 'deli_meat_uncured'];
const MEAT_TIP = { section: 'meat', rule: 'A local butcher comes first; at the case, choose meat from animals raised on grass and open pasture.', checks: ['Ask what the animal ate and how it lived; a butcher counter can answer.', 'Organs come from the same animal; liver and heart belong in the cart too.', 'On packaged meat, look for an ingredient list of meat, salt, and spices.'] };
const COPY_SKIP = new Set(['sources', 'aliases', 'asked_as', 'id', 'category', 'evidence_tier']);
const BRAND = /whole foods|tyson|perdue|hormel|oscar mayer|applegate|boar.s head|smithfield|jimmy dean|hillshire|butterball|jennie-o|foster farms/i;
const CLAIM = /healthier|healthiest|better for you|lowers|exposure|protein|calorie/i;
const PRICE = /\bcheapest\b|\bprice\b|\$[0-9]/i;
const CURE_WORD = /\b(cured|uncured|nitrite|nitrate|celery powder|celery juice)\b/i;

test('C1 D1 limits hold on every CA-3b card', () => {
  for (const id of BATCH) {
    const e = now(id);
    assert.ok(e, `${id} missing`);
    assert.ok(words(e.decision) <= 14, `${id} decision ${words(e.decision)} words`);
    if (Array.isArray(e.pick_steps)) {
      assert.ok(e.pick_steps.length >= 1 && e.pick_steps.length <= 3, `${id} pick_steps ${e.pick_steps.length}`);
      for (const s of e.pick_steps) assert.ok(words(s) <= 14, `${id} pick_step "${s}"`);
    }
    if (e.kind === 'pick') continue;
    const n = String(e.tier_note || '').trim();
    assert.ok(words(n) >= 5 && words(n) <= 20, `${id} tier_note ${words(n)} words`);
    assert.doesNotMatch(n, /[.!?]\s+\S/, `${id} tier_note is more than one sentence`);
    assert.ok(String(e.instead || '').trim().length > 0 && words(e.instead) <= 24, `${id} instead`);
  }
});

test('C2 no CA-3b decision or cart_pick prints a grass term', () => {
  for (const id of BATCH) {
    const e = now(id);
    assert.doesNotMatch(String(e.decision || ''), /grass-(fed|finished)/i, `${id} decision`);
    assert.doesNotMatch(String(e.cart_pick || ''), /grass-(fed|finished)/i, `${id} cart_pick`);
  }
});

test('C3 chicken_breast survives as a rewrite', () => {
  const e = now('chicken_breast');
  assert.ok(e, 'chicken_breast was removed');
  assert.ok(!RETIRED_IDS.has('chicken_breast'), 'chicken_breast is RETIRED');
  assert.match(String(e.cart_pick || ''), /breast/i);
  assert.notEqual(JSON.stringify(e), JSON.stringify(pre('chicken_breast')), 'chicken_breast unchanged');
});

test('C4 the pass rule holds for every CA-3b id', (t) => {
  for (const id of BATCH) pass.assertPassRule(t, pre(id), now(id));
});

test('C5 brand claim and price greps are zero over changed copy fields', () => {
  let changed = 0;
  for (const id of BATCH) {
    const e = now(id);
    const p = pre(id);
    for (const [f, v] of Object.entries(e)) {
      if (COPY_SKIP.has(f) || JSON.stringify(v) === JSON.stringify(p[f])) continue;
      changed++;
      const s = JSON.stringify(v);
      assert.doesNotMatch(s, BRAND, `${id}.${f} brand`);
      assert.doesNotMatch(s, CLAIM, `${id}.${f} claim-lock word`);
      assert.doesNotMatch(s, PRICE, `${id}.${f} price`);
      assert.doesNotMatch(s, /—/, `${id}.${f} em-dash`);
      assert.doesNotMatch(s, /\b(I|me|my|mine)\b/, `${id}.${f} first person`);
    }
  }
  assert.ok(changed >= 14, `only ${changed} changed copy fields`);
});

test('C6 the full meat section is lint-clean under the meat tip', () => {
  const hits = lint.lintSections([{ ...MEAT_TIP, tip_aligned: true, cards_aligned: true }], kb.entries);
  const bad = hits.filter((h) => h.section === 'meat' && ['SECTION_TIP_REPEATS_CARD', 'SECTION_PHRASE_REPEATED', 'TERM_UNGLOSSED', 'CART_PICK_DISAGREES'].includes(h.code));
  assert.deepEqual(bad, []);
});

test('C7 cure sentences come only from the shared set', () => {
  const allowed = new Set(lint.PRESERVATION_CURE_SENTENCES);
  assert.ok(allowed.size > 0, 'PRESERVATION_CURE_SENTENCES empty');
  for (const id of CURED) {
    const e = now(id);
    const p = pre(id);
    for (const f of ['decision', 'tier_note', 'why', 'short_answer', 'kristy_take']) {
      if (JSON.stringify(e[f]) === JSON.stringify(p[f])) continue;
      for (const s of String(e[f] || '').split(/(?<=[.!?])\s+/)) {
        if (CURE_WORD.test(s) && !/^Cured\b|^Uncured\b/.test(s.trim())) assert.ok(allowed.has(s.trim()), `${id}.${f} authored a cure sentence: ${s}`);
      }
    }
  }
});

test('C8 per-card lints are clean and headlines match', () => {
  for (const id of BATCH) {
    const e = now(id);
    if (e.kind === 'pick' || JSON.stringify(e) === JSON.stringify(pre(id))) continue;
    assert.deepEqual(lint.lintCard(projectEntry(e, { doLine: doLines[id] })), [], `${id} lintCard`);
    assert.deepEqual(flat(lint.readability(e)), [], `${id} readability`);
    assert.deepEqual(flat(lint.lintPickSteps(e)), [], `${id} lintPickSteps`);
  }
});
// Pass rule for the readability rewrites (VOICE_SPEC "Readable in the aisle"): rephrasing, never deletion.
import assert from 'node:assert/strict';
import { CULINARY_LEXICON } from '../../lib/counterCardLint.js';
import kb from '../../kristy_perimeter_kb.json' with { type: 'json' };

export const FROZEN = ['id', 'sources', 'aliases', 'asked_as', 'category', 'evidence_tier', 'cart_pick', 'instead', 'labels_decoded'];
export const REWRITABLE = ['decision', 'short_answer', 'why', 'buying_tips', 'watch_out', 'detail', 'kristy_take', 'tier_note', 'eyebrow_short', 'question'];
// Health-first REWRITE ids (docs/plans/card-health-first-plan.md, Piece 4): the approved plan
// re-aims cart_pick, adds asked_as/sources, drops cook-verb aliases and re-words label meanings.
// 4a, 4b and 4c ids; listed together so C12 re-anchors once.
export const HEALTH_FIRST_REWRITE = new Set([
  'ground_beef_lean_ratio', 'beef_cuts_basics', 'beef_grades_usda', 'meat_case', 'butcher_counter_asking',
  'pick_soup_bones', 'egg_grades_sizes', 'pork_cuts_and_enhanced', 'lamb_goat',
  'flour_basics', 'cooking_oils', 'salt', 'sugars', 'maple_syrup', 'cocoa', 'tea', 'broth', 'grains_beyond_rice',
  'bagels', 'pretzels', 'kimchi', 'miso', 'pick_tofu', 'goat_sheep_dairy', 'coconut_milk_beverage',
  // chf-5 fold absorbers: aliases/asked_as gained from retired cards (additive; keepsAll guards losses).
  'chicken_cuts_basics', 'beans_dried_vs_canned',
]);
// Item-card fold survivors and ladder fronts (docs/ITEM-CARDS-PLAN.md IC-3..IC-7): they gain
// aliases/asked_as/sources/labels_decoded from folded cards. chicken_cuts_basics and
// beef_cuts_basics are already in HEALTH_FIRST_REWRITE.
export const ITEM_CARD_REWRITE = new Set([
  'produce_ripeness_by_item', 'berries_picking', 'egg_labels', 'judging_meat_at_the_case', 'seafood_counter',
  'whole_vs_reduced_fat_milk', 'yogurt_plain_vs_flavored', 'plain_kefir', 'organic_worth_it_by_type',
  'beef_grassfed_vs_grainfed', 'salmon_wild_vs_farmed', 'shrimp_imported_vs_domestic', 'grassfed_butter',
  'produce_apples_pears', 'produce_citrus', 'produce_peppers', 'produce_leafy_greens', 'produce_root_vegetables',
  'produce_brassicas', 'produce_onions_garlic', 'produce_green_beans', 'produce_mushrooms', 'produce_stone_fruit',
]);
// Card-alignment rewrites (docs/CARD-ALIGNMENT-PLAN.md milestone 1).
export const CARD_ALIGN_REWRITE = new Set([
  'beef_grassfed_vs_grainfed', 'ground_beef_lean_ratio', 'beef_cuts_basics', 'organ_meats', 'butcher_counter_asking',
  'judging_meat_at_the_case', 'bison', 'venison_game', 'lamb_goat', 'pick_soup_bones',
  'pork_cuts_and_enhanced', 'pick_sausage', 'pick_jerky', 'chicken_cuts_basics', 'chicken_breast',
  'rotisserie_chicken', 'turkey_whole', 'ground_turkey',
  'bacon', 'ham', 'hot_dogs', 'turkey_bacon', 'cured_pork', 'deli_meat_uncured',
  'egg_labels', 'egg_duck_quail', 'pick_egg_whites',
  'whole_vs_reduced_fat_milk', 'raw_milk', 'yogurt_plain_vs_flavored', 'grassfed_butter', 'ghee', 'plain_kefir',
  'raw_kefir', 'sour_cream', 'cream_cheese', 'cottage_cheese', 'cheese_real_vs_processed', 'raw_aged_cheese',
  'goat_sheep_dairy', 'cream_vs_creamer', 'ice_cream', 'dairy_case',
  'almond_milk', 'oat_milk', 'soy_milk', 'coconut_milk_beverage', 'plant_butter',
]);
// alias → ids carrying it in the current KB: an item-card id may drop an alias that moved to another card.
const ALIAS_OWNERS = new Map();
for (const e of kb.entries || []) {
  for (const a of e.aliases || []) {
    if (!ALIAS_OWNERS.has(a)) ALIAS_OWNERS.set(a, new Set());
    ALIAS_OWNERS.get(a).add(e.id);
  }
}
const RELAXED = ['cart_pick', 'asked_as', 'aliases', 'sources', 'labels_decoded'];
const CA_RELAXED = ['cart_pick', 'instead', 'asked_as', 'aliases', 'labels_decoded'];
// By value: sources may be {url, ...} objects, which includes() compares by reference.
const keepsAll = (newList, oldList) => {
  const have = new Set((newList || []).map((x) => JSON.stringify(x)));
  return (oldList || []).every((x) => have.has(JSON.stringify(x)));
};

const NUMBER = /\d+(?:[.,]\d+)?%?/g;
const isEmpty = (v) => v == null || (typeof v === 'string' ? v.trim() === '' : Array.isArray(v) && v.length === 0);

export function assertPassRule(t, oldEntry, newEntry) {
  const id = oldEntry.id;
  const hf = HEALTH_FIRST_REWRITE.has(id) || ITEM_CARD_REWRITE.has(id);
  const ca = CARD_ALIGN_REWRITE.has(id);
  const rewrite = hf || ca;
  for (const f of FROZEN) {
    if ((hf && RELAXED.includes(f)) || (ca && CA_RELAXED.includes(f))) continue;
    assert.deepEqual(newEntry[f], oldEntry[f], `${id}: frozen field ${f} changed`);
  }
  if (rewrite) {
    assert.ok(keepsAll(newEntry.asked_as, oldEntry.asked_as), `${id}: asked_as lost a phrasing`);
    assert.ok(keepsAll(newEntry.sources, oldEntry.sources), `${id}: sources lost an entry`);
    for (const a of oldEntry.aliases || []) {
      if (!(newEntry.aliases || []).includes(a)) {
        assert.ok(
          CULINARY_LEXICON.test(a) || (ITEM_CARD_REWRITE.has(id) && [...(ALIAS_OWNERS.get(a) ?? [])].some((o) => o !== id)),
          `${id}: alias "${a}" dropped but is not a cook-verb alias and no other card carries it`
        );
      }
    }
    const terms = (newEntry.labels_decoded || []).map((l) => l.term);
    for (const l of oldEntry.labels_decoded || []) assert.ok(terms.includes(l.term), `${id}: label term "${l.term}" dropped`);
  }
  for (const [f, v] of Object.entries(oldEntry)) {
    if (!isEmpty(v)) assert.ok(!isEmpty(newEntry[f]), `${id}: ${f} was non-empty and is now empty`);
  }
  assert.ok((newEntry.watch_out || []).length >= (oldEntry.watch_out || []).length, `${id}: watch_out lost an item`);
  const oldText = REWRITABLE.map((f) => JSON.stringify(oldEntry[f] ?? '')).join(' ');
  // Rewritable fields only: a number surviving in a source URL is not a surviving fact.
  const newText = REWRITABLE.map((f) => JSON.stringify(newEntry[f] ?? '')).join(' ');
  for (const n of new Set(oldText.match(NUMBER) || [])) {
    assert.ok(newText.includes(n), `${id}: number ${n} from the old text is gone`);
  }
}
